  588,
  'gates-cambridge-scholarship-2027',
  'Gates Cambridge Scholarship 2027 – Fully Funded Postgraduate Scholarship',
  'scholarships',
  'Gates Cambridge Trust & University of Cambridge',
  'Fully Funded Postgraduate Scholarship',
  'Cambridge, United Kingdom',
  'Bachelor''s / Master''s Degree (First Class Honours / High Academic Standing)',
  '100% University Composition Fee + ~£21,000 Annual Living Allowance + Airfare + Visa',
  '2026-12-08',
